SELECT analytics_order_facts.customer_segment, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 1 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.category = 'category_04' GROUP BY analytics_order_facts.customer_segment ORDER BY order_count DESC, analytics_order_facts.customer_segment ASC LIMIT 6
